'use client';

import { SwapProvider, SwapQuote, SwapQuoteParams, TransactionState, WalletId } from '@pollar/core';
import { useState } from 'react';
import { AssetSelect } from '../AssetSelect';
import { PollarModalFooter } from '../commons';
import { TxStatusView } from '../transaction-modal/TxStatusView';
import { buildModalCssVars, type ModalStyleOverrides } from '../modal-theme';

/** A selectable asset in the sell/buy pickers, normalized across balance/enabled records. */
export interface SwapAssetOption {
  ref: SwapQuoteParams['sellAsset'];
  code: string;
  issuer?: string | undefined;
  available?: string | undefined;
  enabledInApp?: boolean | undefined;
}

export function assetOptionKey(o: SwapAssetOption): string {
  return `${o.code}:${o.issuer ?? 'native'}`;
}

const PROVIDER_LABELS: Record<SwapProvider, string> = {
  auto: 'Best price (auto)',
  aquarius: 'Aquarius',
  soroswap: 'Soroswap',
  sdex: 'Stellar DEX',
};

function formatAmount(value: string): string {
  const n = parseFloat(value);
  return isNaN(n) ? value : n.toLocaleString(undefined, { maximumFractionDigits: 7 });
}

export interface SwapModalTemplateProps {
  theme: string;
  accentColor: string;
  /** Per-app modal chrome overrides (background, card + button radius). */
  styleOverrides?: ModalStyleOverrides;
  step: 'form' | 'tx';
  txTitle: string;
  sellOptions: SwapAssetOption[];
  buyOptions: SwapAssetOption[];
  selectedSell: SwapAssetOption | null;
  selectedBuy: SwapAssetOption | null;
  amount: string;
  provider: SwapProvider;
  providers: SwapProvider[];
  quote: SwapQuote | null;
  quoteLoading: boolean;
  quoteError: string;
  formError: string;
  isLoadingData: boolean;
  smartUnsupported: boolean;
  /** Swap config is still loading. */
  configLoading: boolean;
  /** Config loaded and this app exposes no swap venues - swap is disabled. */
  swapUnavailable: boolean;
  /** Buying the selected asset will create a trustline first (~0.5 XLM reserve). */
  buyNeedsTrustline: boolean;
  transaction: TransactionState;
  showXdr: boolean;
  copied: boolean;
  explorerUrl: string | null;
  walletType?: WalletId | null | undefined;
  showBack: boolean;
  isInProgress: boolean;
  onClose: () => void;
  onBack: () => void;
  onRefresh: () => void;
  onSelectSell: (o: SwapAssetOption) => void;
  onSelectBuy: (o: SwapAssetOption) => void;
  /** Add a user-pasted token (code + issuer) to the buy list. Returns an error or null. */
  onAddCustomToken: (code: string, issuer: string) => string | null;
  onAmountChange: (value: string) => void;
  onProviderChange: (p: SwapProvider) => void;
  onSwap: () => void;
  onToggleXdr: () => void;
  onCopyHash: () => void;
  onRetry: () => void;
  onDone: () => void;
}

export function SwapModalTemplate({
  theme,
  accentColor,
  styleOverrides,
  step,
  txTitle,
  sellOptions,
  buyOptions,
  selectedSell,
  selectedBuy,
  amount,
  provider,
  providers,
  quote,
  quoteLoading,
  quoteError,
  formError,
  isLoadingData,
  smartUnsupported,
  configLoading,
  swapUnavailable,
  buyNeedsTrustline,
  transaction,
  showXdr,
  copied,
  explorerUrl,
  walletType,
  showBack,
  isInProgress,
  onClose,
  onBack,
  onRefresh,
  onSelectSell,
  onSelectBuy,
  onAddCustomToken,
  onAmountChange,
  onProviderChange,
  onSwap,
  onToggleXdr,
  onCopyHash,
  onRetry,
  onDone,
}: SwapModalTemplateProps) {
  const [customOpen, setCustomOpen] = useState(false);
  const [customCode, setCustomCode] = useState('');
  const [customIssuer, setCustomIssuer] = useState('');
  const [customError, setCustomError] = useState('');

  const submitCustomToken = () => {
    const err = onAddCustomToken(customCode, customIssuer);
    if (err) {
      setCustomError(err);
      return;
    }
    setCustomCode('');
    setCustomIssuer('');
    setCustomError('');
    setCustomOpen(false);
  };

  const cssVars = buildModalCssVars(theme, accentColor, styleOverrides);

  const sellKey = selectedSell ? assetOptionKey(selectedSell) : '';
  const buyKey = selectedBuy ? assetOptionKey(selectedBuy) : '';
  const canSwap =
    !smartUnsupported && !!selectedSell && !!selectedBuy && !!amount && !!quote && !quoteLoading && !isLoadingData;

  const title = step === 'form' ? 'Swap' : txTitle;

  return (
    <div
      className="pollar-modal-card pollar-send-modal"
      data-theme={theme}
      style={cssVars}
      onClick={(e) => e.stopPropagation()}
    >
      <div className="pollar-modal-header">
        <div className="pollar-send-header-left">
          {showBack && (
            <button type="button" className="pollar-modal-close" onClick={onBack} aria-label="Back">
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
                <path d="M10 3L5 8l5 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
          )}
          <h2 className="pollar-modal-title">{title}</h2>
        </div>
        {!isInProgress && (
          <div className="pollar-modal-header-actions">
            {step === 'form' && (
              <button
                type="button"
                className="pollar-modal-close"
                onClick={onRefresh}
                disabled={configLoading || isLoadingData}
                aria-label="Refresh"
                title="Refresh balances and options"
              >
                <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
                  <path
                    d="M13.5 8a5.5 5.5 0 1 1-1.6-3.9M13.5 2.5v3h-3"
                    stroke="currentColor"
                    strokeWidth="1.6"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </button>
            )}
            <button type="button" className="pollar-modal-close" onClick={onClose} aria-label="Close">
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
                <path d="M2 2l12 12M14 2L2 14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
              </svg>
            </button>
          </div>
        )}
      </div>

      {step === 'form' && !configLoading && swapUnavailable && (
        <div className="pollar-modal-error">Swap is not available for this app.</div>
      )}

      {/* Keep the form visible while the config loads - disable the inputs rather
          than unmounting them, so the modal doesn't visibly collapse/jump. */}
      {step === 'form' && !swapUnavailable && (
        <>
          {smartUnsupported && (
            <div className="pollar-modal-error">Swaps are not yet available for smart (passkey) wallets.</div>
          )}

          {/* Sell asset */}
          <AssetSelect
            label="You pay"
            value={sellKey}
            loading={isLoadingData || configLoading}
            loadingLabel="Loading assets…"
            disabled={configLoading}
            options={sellOptions.map((o) => ({
              key: assetOptionKey(o),
              code: o.code,
              available: o.available,
              enabledInApp: o.enabledInApp,
            }))}
            onChange={(key) => {
              const found = sellOptions.find((o) => assetOptionKey(o) === key);
              if (found) onSelectSell(found);
            }}
          />

          {/* Amount */}
          <div className="pollar-send-field">
            <div className="pollar-send-label-row">
              <label className="pollar-send-label">Amount</label>
              {selectedSell?.available !== undefined && (
                <span className="pollar-send-hint">
                  Available: {formatAmount(selectedSell.available)} {selectedSell.code}
                </span>
              )}
            </div>
            <input
              className="pollar-input"
              type="text"
              inputMode="decimal"
              placeholder="0.00"
              value={amount}
              disabled={configLoading}
              onChange={(e) => onAmountChange(e.target.value)}
            />
          </div>

          {/* Buy asset */}
          <AssetSelect
            label="You receive"
            value={buyKey}
            loading={isLoadingData || configLoading}
            loadingLabel="Loading assets…"
            disabled={configLoading}
            options={buyOptions.map((o) => ({
              key: assetOptionKey(o),
              code: o.code,
              enabledInApp: o.enabledInApp,
            }))}
            onChange={(key) => {
              const found = buyOptions.find((o) => assetOptionKey(o) === key);
              if (found) onSelectBuy(found);
            }}
          >
            {customOpen ? (
              <div className="pollar-swap-custom">
                <input
                  className="pollar-input"
                  type="text"
                  placeholder="Code (e.g. USDC)"
                  value={customCode}
                  onChange={(e) => setCustomCode(e.target.value)}
                />
                <input
                  className="pollar-input"
                  type="text"
                  placeholder="Issuer (G...)"
                  value={customIssuer}
                  onChange={(e) => setCustomIssuer(e.target.value)}
                />
                {customError && <div className="pollar-modal-error">{customError}</div>}
                <div className="pollar-swap-custom-actions">
                  <button type="button" className="pollar-btn-primary" onClick={submitCustomToken}>
                    Add token
                  </button>
                  <button
                    type="button"
                    className="pollar-swap-custom-cancel"
                    onClick={() => {
                      setCustomOpen(false);
                      setCustomError('');
                    }}
                  >
                    Cancel
                  </button>
                </div>
              </div>
            ) : (
              <button
                type="button"
                className="pollar-swap-custom-toggle"
                disabled={configLoading}
                onClick={() => setCustomOpen(true)}
              >
                + Add a token by code / issuer
              </button>
            )}
          </AssetSelect>

          {/* Route selector */}
          <div className="pollar-send-field">
            <label className="pollar-send-label">Route</label>
            {configLoading ? (
              <div className="pollar-input pollar-select-loading">
                <span className="pollar-spinner pollar-spinner-sm" />
                <span>Loading routes…</span>
              </div>
            ) : (
              <select
                className="pollar-input pollar-send-select"
                value={provider}
                disabled={providers.length === 0}
                onChange={(e) => onProviderChange(e.target.value as SwapProvider)}
              >
                {providers.length === 0 ? (
                  <option value={provider}>{PROVIDER_LABELS[provider]}</option>
                ) : (
                  providers.map((p) => (
                    <option key={p} value={p}>
                      {PROVIDER_LABELS[p]}
                    </option>
                  ))
                )}
              </select>
            )}
          </div>

          {/* Quote panel */}
          {quoteLoading && (
            <div className="pollar-send-hint pollar-inline-loading">
              <span className="pollar-spinner pollar-spinner-sm" />
              Fetching best price…
            </div>
          )}
          {!quoteLoading && quoteError && <div className="pollar-modal-error">{quoteError}</div>}
          {!quoteLoading && !quoteError && quote && selectedBuy && (
            <div className="pollar-swap-quote">
              <div className="pollar-swap-quote-row">
                <span className="pollar-send-hint">You receive</span>
                <span>
                  ~ {formatAmount(quote.amountOut)} {selectedBuy.code}
                </span>
              </div>
              <div className="pollar-swap-quote-row">
                <span className="pollar-send-hint">Minimum received</span>
                <span>
                  {formatAmount(quote.minReceived)} {selectedBuy.code}
                </span>
              </div>
              <div className="pollar-swap-quote-row">
                <span className="pollar-send-hint">Price impact</span>
                <span>{quote.priceImpactPct}%</span>
              </div>
              <div className="pollar-swap-quote-row">
                <span className="pollar-send-hint">Route</span>
                <span>{PROVIDER_LABELS[quote.provider]}</span>
              </div>
            </div>
          )}
          {!quoteLoading && !quoteError && !quote && selectedSell && selectedBuy && !!amount && (
            <div className="pollar-send-hint">No route found for this pair.</div>
          )}

          {buyNeedsTrustline && selectedBuy && (
            <div className="pollar-swap-trustline-notice">
              To receive {selectedBuy.code} your wallet needs a trustline. Swapping will create it first (~0.5 XLM reserve,
              refundable if you later remove it).
            </div>
          )}

          {formError && <div className="pollar-modal-error">{formError}</div>}

          <div className="pollar-modal-actions">
            <button className="pollar-btn-primary" onClick={onSwap} disabled={!canSwap}>
              {buyNeedsTrustline ? 'Create trustline & swap' : 'Swap'}
            </button>
          </div>
        </>
      )}

      {step === 'tx' && (
        <TxStatusView
          transaction={transaction}
          showXdr={showXdr}
          copied={copied}
          explorerUrl={explorerUrl}
          walletType={walletType}
          onSignAndSend={() => {}}
          onToggleXdr={onToggleXdr}
          onCopyHash={onCopyHash}
          onRetry={onRetry}
          onDone={onDone}
        />
      )}

      <PollarModalFooter />
    </div>
  );
}
